import AppKit

struct WorkflowEncodedImageResult {
    let data: Data
    let outputURL: URL
}

enum WorkflowImagePersistenceLogic {
    typealias UniqueURLResolver = (_ proposedName: String, _ directory: URL) -> URL

    /// Originals larger than this are not embedded, to avoid bloating saved files.
    /// Generous enough that real screenshots (incl. full-screen Retina PNGs)
    /// always round-trip; only pathologically large originals are skipped.
    static let maxEmbeddedOriginalBytes = 50 * 1024 * 1024

    static func encodedImageData(from image: NSImage,
                                 originalURL: URL,
                                 cleanOriginalPNG: Data? = nil,
                                 prompt: String? = nil,
                                 editorState: EditorCanvasState? = nil,
                                 uniqueURL: UniqueURLResolver) -> WorkflowEncodedImageResult? {
        // PNG-only: every image is encoded as PNG regardless of the original
        // file's extension.
        let ext = originalURL.pathExtension.lowercased()

        guard let bitmap = ScreenshotServiceCoreLogic.bitmapRepresentation(from: image) else { return nil }
        guard var data = bitmap.representation(using: .png, properties: [:]) else { return nil }

        // Round-trip metadata: embed the clean original + prompt and/or editable
        // canvas state when present.
        if let prompt, !prompt.isEmpty,
           let cleanOriginalPNG, cleanOriginalPNG.count < maxEmbeddedOriginalBytes,
           let embedded = PNGMetadata.embed(intoPNG: data,
                                            originalPNG: cleanOriginalPNG,
                                            prompt: prompt,
                                            editorState: editorState) {
            data = embedded
        } else if let editorState,
                  editorState.baseImagePNG.count < maxEmbeddedOriginalBytes,
                  let embedded = PNGMetadata.embed(intoPNG: data, editorState: editorState) {
            data = embedded
        }

        let outputURL: URL
        if ext != "png" && !ext.isEmpty {
            // Original wasn't a PNG (e.g. an opened JPEG/HEIC). Rewrite as .png.
            let proposedName = originalURL.deletingPathExtension().lastPathComponent + ".png"
            outputURL = uniqueURL(proposedName, originalURL.deletingLastPathComponent())
        } else {
            outputURL = originalURL
        }

        return WorkflowEncodedImageResult(data: data, outputURL: outputURL)
    }

    static func writeEncodedImageData(_ data: Data,
                                      to outputURL: URL,
                                      originalURL: URL,
                                      fileManager: FileManager = .default) throws -> URL {
        try data.write(to: outputURL, options: .atomic)

        if outputURL != originalURL, fileManager.fileExists(atPath: originalURL.path) {
            try? fileManager.removeItem(at: originalURL)
        }

        return outputURL
    }
}

import Foundation

/// Embeds and extracts Zoomies round-trip metadata in PNG text chunks so a
/// saved screenshot can carry its clean (pre-note) original plus the prompt
/// text that was burned onto it.
///
/// We manipulate PNG chunks directly instead of going through ImageIO's
/// `kCGImagePropertyPNGDictionary`: that dictionary only round-trips a fixed set
/// of standard tEXt keywords (Title, Author, Description, ...) and cannot write
/// the custom keywords this feature needs. The payloads are stored in
/// uncompressed `iTXt` chunks, which are UTF-8 safe.
enum PNGMetadata {
    /// Keyword for the base64-encoded clean original PNG.
    static let originalPNGKeyword = "Zoomies-OriginalPNG-v1"
    /// Keyword for the UTF-8 prompt text.
    static let promptKeyword = "Zoomies-Prompt-v1"
    /// Keyword for the JSON-encoded editable canvas state.
    static let editorStateKeyword = "Zoomies-EditorState-v1"

    private static let signature: [UInt8] = [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]

    /// Inserts the original PNG bytes and prompt as `iTXt` chunks just before
    /// `IEND`. Returns nil if either input is not a PNG, or the input PNG is
    /// malformed.
    static func embed(intoPNG pngData: Data,
                      originalPNG: Data,
                      prompt: String,
                      editorState: EditorCanvasState? = nil) -> Data? {
        let bytes = [UInt8](pngData)
        guard hasPNGSignature(bytes), isPNG(originalPNG) else { return nil }
        guard let iendStart = indexOfChunk(named: "IEND", in: bytes) else { return nil }

        var result = Data()
        result.append(stripZoomiesChunks(from: bytes[0..<iendStart]))
        result.append(makeITXtChunk(keyword: originalPNGKeyword, text: originalPNG.base64EncodedString()))
        result.append(makeITXtChunk(keyword: promptKeyword, text: prompt))
        if let editorStateText = encodeEditorState(editorState) {
            result.append(makeITXtChunk(keyword: editorStateKeyword, text: editorStateText))
        }
        result.append(contentsOf: bytes[iendStart...])
        return result
    }

    static func embed(intoPNG pngData: Data, editorState: EditorCanvasState) -> Data? {
        let bytes = [UInt8](pngData)
        guard hasPNGSignature(bytes) else { return nil }
        guard let iendStart = indexOfChunk(named: "IEND", in: bytes),
              let editorStateText = encodeEditorState(editorState) else { return nil }

        var result = Data()
        result.append(stripZoomiesChunks(from: bytes[0..<iendStart]))
        result.append(makeITXtChunk(keyword: editorStateKeyword, text: editorStateText))
        result.append(contentsOf: bytes[iendStart...])
        return result
    }

    /// Extracts the embedded clean original and prompt. Returns nil for non-PNG
    /// input, when either chunk is missing, or when a chunk/original image
    /// exceeds safety limits.
    static func extract(fromPNG pngData: Data,
                        limits: ImageSafetyLimits = .runtime) -> (originalPNG: Data, prompt: String)? {
        let bytes = [UInt8](pngData)
        guard hasPNGSignature(bytes) else { return nil }

        var original: Data?
        var prompt: String?
        var index = 8
        while index + 8 <= bytes.count {
            guard let length = readUInt32(bytes, at: index) else { break }
            let typeStart = index + 4
            let dataStart = typeStart + 4
            let len = Int(length)
            guard dataStart + len + 4 <= bytes.count else { break }

            let type = String(bytes: bytes[typeStart..<dataStart], encoding: .ascii) ?? ""
            if type == "iTXt" {
                if isKeyword(originalPNGKeyword, in: bytes, dataStart: dataStart, length: len) {
                    if len > limits.maxOriginalPNGChunkBytes {
                        return nil
                    }

